export function StabilizationCenterPanel({ projects, users, onReloadProjects }: { projects: Project[]; users: UserActivitySummary[]; onReloadProjects: () => Promise<void> }) {
  const [diagnostics, setDiagnostics] = useState<StabilizationDiagnostic | null>(null);
  const [status, setStatus] = useState("Ready to run stabilization checks.");
  const [busy, setBusy] = useState(false);
  async function loadChecks() {
    setBusy(true);
    try {
      const result = await api<StabilizationDiagnostic>("/api/admin/stabilization");
      setDiagnostics(result);
      setStatus(`Loaded ${result.checks.length} stabilization check${result.checks.length === 1 ? "" : "s"}.`);
    } catch (err) {
      setStatus(err instanceof Error ? err.message : "Stabilization diagnostics failed.");
    } finally {
      setBusy(false);
    }
  }
  async function seedDemoWorkspace() {
    setBusy(true);
    try {
      const result = await api<{
        ok: boolean;
        created: string[];
        counts: Record<string, number>;
        message: string;
      }>("/api/admin/demo-workspace", { method: "POST" });
      setStatus(result.message || `Seeded demo workspace with ${result.created.length} created item${result.created.length === 1 ? "" : "s"}.`);
      await onReloadProjects();
      await loadChecks();
    } catch (err) {
      setStatus(err instanceof Error ? err.message : "Demo seed failed.");
    } finally {
      setBusy(false);
    }
  }
  useEffect(() => {
    loadChecks().catch(() => undefined);
  }, []);
  const localCommands = diagnostics?.localCommands || ["npm install", "npm run db:deploy", "npm run build", "npm run dev"];
  const passCount = diagnostics?.checks.filter((item) => item.status === "pass").length || 0;
  const warnCount = diagnostics?.checks.filter((item) => item.status === "warn").length || 0;
  const failCount = diagnostics?.checks.filter((item) => item.status === "fail").length || 0;
  const demoReady = projects.length >= 2 && users.length >= 3;
  return (
    <section className="stabilization-center-v128">
      <div className="panel stabilization-hero-v128">
        <div>
          <p className="eyebrow">Stabilization</p>
          <h2>Production QA pass</h2>
          <p className="muted tight">Run build, migration, persistence, security, demo-data, and CI readiness checks.</p>
          <div className="ops-hero-meta-v072">
            <span>{projects.length} projects</span>
            <span>{users.length} users</span>
            <span>{passCount} pass</span>
            <span>{warnCount} warning</span>
            <span>{failCount} fail</span>
          </div>
        </div>
        <div className="button-row">
          <ClusterButton type="button" className="" disabled={busy} onClick={loadChecks} variant="secondary">
            Refresh checks
          </ClusterButton>
          <ClusterButton type="button" className="" disabled={busy} onClick={seedDemoWorkspace} variant="primary">
            {demoReady ? "Refresh demo seed" : "Seed demo workspace"}
          </ClusterButton>
        </div>
      </div>

      <div className="stabilization-grid-v128">
        <section className="panel stabilization-card-v128">
          <div className="section-heading">
            <div>
              <p className="eyebrow">Local QA</p>
              <h3>Build commands</h3>
              <p className="muted tight">Run these commands locally after installing dependencies.</p>
            </div>
            <span className="soft-pill">Manual</span>
          </div>
          <ol className="command-list-v128">
            {localCommands.map((command) => (
              <li key={command}>
                <code>{command}</code>
              </li>
            ))}
          </ol>
        </section>

        <section className="panel stabilization-card-v128">
          <div className="section-heading">
            <div>
              <p className="eyebrow">Database</p>
              <h3>Migration sanity</h3>
            </div>
            <span className="soft-pill">{diagnostics ? levelLabel(diagnostics.version) : "loading"}</span>
          </div>
          <div className="stabilization-check-list-v128">
            {(diagnostics?.checks || []).map((check) => (
              <article key={check.key} className={check.status}>
                <strong>{check.label}</strong>
                <span>{check.detail}</span>
                <em>{check.status}</em>
              </article>
            ))}
          </div>
        </section>

        <section className="panel stabilization-card-v128">
          <div className="section-heading">
            <div>
              <p className="eyebrow">Persistence</p>
              <h3>State audit</h3>
            </div>
          </div>
          <div className="persistence-list-v128">
            {(diagnostics?.persistence || []).map((item) => (
              <article key={item.system} className={item.status}>
                <strong>{item.system}</strong>
                <span>{item.storage}</span>
                <p>{item.note}</p>
              </article>
            ))}
          </div>
        </section>

        <section className="panel stabilization-card-v128">
          <div className="section-heading">
            <div>
              <p className="eyebrow">Security</p>
              <h3>Auth hardening</h3>
            </div>
          </div>
          <div className="stabilization-check-list-v128 compact">
            {(diagnostics?.security || []).map((item) => (
              <article key={item.label} className={item.status}>
                <strong>{item.label}</strong>
                <span>{item.detail}</span>
                <em>{item.status}</em>
              </article>
            ))}
          </div>
        </section>
      </div>

      <section className="panel stabilization-card-v128 demo-seed-v128">
        <div className="section-heading">
          <div>
            <p className="eyebrow">Demo workspace</p>
            <h3>Sample production data</h3>
            <p className="muted tight">Seeds an internal project, an external project, users, boards, cards, timeline items, library documents, whiteboards, and activity.</p>
          </div>
          <span className="soft-pill">{demoReady ? "Seeded-ish" : "Recommended"}</span>
        </div>
        <div className="demo-seed-grid-v128">
          <article>
            <strong>Internal project</strong>
            <span>Gameplay slice with QA/report/build-ish sample cards.</span>
          </article>
          <article>
            <strong>External project</strong>
            <span>Partner-facing project to test external permissions.</span>
          </article>
          <article>
            <strong>Production context</strong>
            <span>Timeline, library lifecycle docs, whiteboard items, and audit activity.</span>
          </article>
        </div>
      </section>

      <section className="panel stabilization-card-v128 docs-ci-v128">
        <div className="section-heading">
          <div>
            <p className="eyebrow">CI + docs</p>
            <h3>Operational checklist</h3>
          </div>
          <span className="soft-pill">Added files</span>
        </div>
        <div className="docs-ci-grid-v128">
          <article>
            <strong>.github/workflows/cluster-ci.yml</strong>
            <span>Install, Prisma generate, type/build checks.</span>
          </article>
          <article>
            <strong>docs/LOCAL_QA.md</strong>
            <span>Manual build, migration, permission, and screenshot QA flow.</span>
          </article>
          <article>
            <strong>docs/STABILIZATION.md</strong>
            <span>Production hardening notes, persistence review, auth, and backup guidance.</span>
          </article>
        </div>
      </section>

      {status && <div className="status-box system-status-box-v053">{status}</div>}
    </section>
  );
}

export function ImportToolsPanel({ projects, users, onReloadProjects }: { projects: Project[]; users: UserActivitySummary[]; onReloadProjects: () => Promise<void> }) {
  const [usersCsv, setUsersCsv] = useState("username,employeeNumber,displayName,email,title,teamName,role\njdoe,EMP-0001,Jane Doe,jane@example.com,Developer,Core,member");
  const [cardsCsv, setCardsCsv] = useState("title,description,priority,labels\nFix save bug,Save menu fails after reload,high,bug;qa");
  const [projectJson, setProjectJson] = useState('[{"name":"External Playtest","description":"Imported project shell","projectType":"game","productionProfile":"unreal","status":"active","external":true}]');
  const [libraryCsv, setLibraryCsv] = useState("title,type,status,body,tags,versionLabel\nCombat spec,spec,draft,Core combat loop notes,combat;design,v0.1");
  const [targetListId, setTargetListId] = useState("");
  const [targetProjectId, setTargetProjectId] = useState(projects[0]?.id || "");
  const [preview, setPreview] = useState<ImportPreviewRecord[]>([]);
  const [restoreText, setRestoreText] = useState("");
  const [restorePlan, setRestorePlan] = useState<any | null>(null);
  const [restoreSections, setRestoreSections] = useState<Record<string, boolean>>({
    projects: true,
    users: false,
    permissions: false,
    hours: false,
    library: true,
  });
  const [status, setStatus] = useState("Import tools ready.");
  const listOptions = useMemo(() => projects.flatMap((project) => (project.boards || []).flatMap((board) => (board.lists || []).map((list) => ({ project, board, list })))), [projects]);
  useEffect(() => {
    if (!targetListId && listOptions[0]) setTargetListId(listOptions[0].list.id);
    if (!targetProjectId && projects[0]) setTargetProjectId(projects[0].id);
  }, [listOptions, projects, targetListId, targetProjectId]);
  function setRows(type: string, rows: ImportPreviewRecord[]) {
    setPreview((prev) => [...rows, ...prev.filter((item) => item.type !== type)].slice(0, 80));
  }
  async function importUsers() {
    const rows = parseCsvObjects(usersCsv);
    const next: ImportPreviewRecord[] = [];
    type ImportTeam = { id: string; name: string; revision?: number; members: Array<{ userId: string; teamRoleId?: string | null; roleLabel?: string | null; allocationPercent: number; primaryMembership: boolean }> };
    let teams = await api<ImportTeam[]>("/api/team/teams").catch(() => [] as ImportTeam[]);
    for (const row of rows) {
      const username =
        row.username ||
        row.user ||
        row.name
          ?.toLowerCase()
          .replace(/[^a-z0-9]+/g, ".")
          .replace(/^\.|\.$/g, "");
      if (!username) continue;
      try {
        const created = await api<User>("/api/users", {
          method: "POST",
          body: JSON.stringify({
            username,
            employeeNumber: row.employeenumber || row.employeeid || null,
            displayName: row.displayname || row.name || username,
            email: row.email || null,
            title: row.title || null,
            role: row.role || "member",
            capacityHours: row.capacityhours ? Number(row.capacityhours) : null,
          }),
        });
        const teamName = String(row.teamname || row.team || "").trim();
        if (teamName) {
          let team = teams.find((item) => item.name.localeCompare(teamName, undefined, { sensitivity: "accent" }) === 0);
          if (!team) {
            team = await api<ImportTeam>("/api/team/teams", { method: "POST", body: JSON.stringify({ name: teamName }) });
            teams = [...teams, team];
          }
          if (!team.members.some((member) => member.userId === created.id)) {
            const updated = await api<ImportTeam>(`/api/team/teams/${team.id}/members`, {
              method: "PUT",
              body: JSON.stringify({
                expectedRevision: team.revision,
                members: [
                  ...team.members.map((member) => ({ userId: member.userId, teamRoleId: member.teamRoleId || null, roleLabel: member.roleLabel || null, allocationPercent: member.allocationPercent, primaryMembership: member.primaryMembership })),
                  { userId: created.id, allocationPercent: 100, primaryMembership: true },
                ],
              }),
            });
            teams = teams.map((item) => item.id === updated.id ? updated : item);
          }
        }
        next.push({
          id: localId("import-user"),
          type: "users",
          title: username,
          detail: teamName ? `${row.email || row.title || "User imported"} · ${teamName}` : row.email || row.title || "User imported",
          status: "imported",
        });
      } catch (err) {
        next.push({
          id: localId("import-user"),
          type: "users",
          title: username,
          detail: "User import failed",
          status: "error",
          error: err instanceof Error ? err.message : "Import failed",
        });
      }
    }
    setRows("users", next);
    setStatus(`Processed ${next.length} user row${next.length === 1 ? "" : "s"}.`);
  }
  async function importCards() {
    if (!targetListId) {
      setStatus("Pick a target list before importing cards.");
      return;
    }
    const rows = parseCsvObjects(cardsCsv);
    const next: ImportPreviewRecord[] = [];
    for (const row of rows) {
      const title = row.title || row.name;
      if (!title) continue;
      try {
        await api<Card>("/api/cards", {
          method: "POST",
          body: JSON.stringify({
            listId: targetListId,
            title,
            description: row.description || row.body || null,
            priority: (row.priority || "medium").toLowerCase(),
            labels: unique((row.labels || row.tags || "").split(/[;,]/)),
          }),
        });
        next.push({
          id: localId("import-card"),
          type: "cards",
          title,
          detail: row.priority || "medium",
          status: "imported",
        });
      } catch (err) {
        next.push({
          id: localId("import-card"),
          type: "cards",
          title,
          detail: "Card import failed",
          status: "error",
          error: err instanceof Error ? err.message : "Import failed",
        });
      }
    }
    setRows("cards", next);
    setStatus(`Processed ${next.length} card row${next.length === 1 ? "" : "s"}.`);
    await onReloadProjects();
  }
  async function importProjectsJson() {
    const parsed = JSON.parse(projectJson || "[]");
    const rows = Array.isArray(parsed) ? parsed : [parsed];
    const next: ImportPreviewRecord[] = [];
    for (const item of rows) {
      if (!item?.name) continue;
      try {
        await api<Project>("/api/projects", {
          method: "POST",
          body: JSON.stringify({
            name: item.name,
            description: item.description || null,
            projectType: item.projectType || item.type || "general",
            productionProfile: item.productionProfile || item.profile || "generic",
            status: item.status || "active",
            external: Boolean(item.external),
            memberIds: Array.isArray(item.memberIds) ? item.memberIds : [],
            createDefaultBoard: Boolean(item.createDefaultBoard ?? true),
            boardName: item.boardName || "Imported Board",
            createWhiteboard: Boolean(item.createWhiteboard ?? false),
            createLibraryFolder: Boolean(item.createLibraryFolder ?? false),
          }),
        });
        next.push({
          id: localId("import-project"),
          type: "projects",
          title: item.name,
          detail: item.external ? "External" : "Internal",
          status: "imported",
        });
      } catch (err) {
        next.push({
          id: localId("import-project"),
          type: "projects",
          title: item.name,
          detail: "Project import failed",
          status: "error",
          error: err instanceof Error ? err.message : "Import failed",
        });
      }
    }
    setRows("projects", next);
    setStatus(`Processed ${next.length} project record${next.length === 1 ? "" : "s"}.`);
    await onReloadProjects();
  }
  async function importLibraryBulk() {
    const rows = parseCsvObjects(libraryCsv);
    const next: ImportPreviewRecord[] = [];
    for (const row of rows) {
      const title = row.title || row.name;
      if (!title) continue;
      try {
        await api<LibraryItem>("/api/library", {
          method: "POST",
          body: JSON.stringify({
            projectId: targetProjectId || null,
            title,
            body: row.body || row.description || null,
            type: row.type || "note",
            status: row.status || "draft",
            priority: row.priority || "medium",
            tags: unique((row.tags || "").split(/[;,]/)),
            versionLabel: row.versionlabel || row.version || null,
            visibility: row.visibility || "internal",
          }),
        });
        next.push({
          id: localId("import-library"),
          type: "library",
          title,
          detail: row.type || "note",
          status: "imported",
        });
      } catch (err) {
        next.push({
          id: localId("import-library"),
          type: "library",
          title,
          detail: "Library import failed",
          status: "error",
          error: err instanceof Error ? err.message : "Import failed",
        });
      }
    }
    setRows("library", next);
    setStatus(`Processed ${next.length} library row${next.length === 1 ? "" : "s"}.`);
  }
  function stageRestorePlan() {
    try {
      const parsed = JSON.parse(restoreText || "{}");
      const payload = parsed.payload || parsed;
      const plan = {
        id: localId("restore-plan"),
        stagedAt: new Date().toISOString(),
        version: parsed.manifest?.version || parsed.version || "unknown",
        sections: {
          projects: Array.isArray(payload.projects) ? payload.projects.length : Array.isArray(parsed.projects) ? parsed.projects.length : 0,
          users: Array.isArray(payload.users) ? payload.users.length : Array.isArray(parsed.users) ? parsed.users.length : 0,
          permissions: Array.isArray(payload.permissions) ? payload.permissions.length : Array.isArray(parsed.permissions) ? parsed.permissions.length : 0,
          hours: Array.isArray(payload.hours?.entries) ? payload.hours.entries.length : Array.isArray(parsed.hours?.entries) ? parsed.hours.entries.length : 0,
          library: Array.isArray(payload.library) ? payload.library.length : Array.isArray(parsed.library) ? parsed.library.length : 0,
        },
        conflicts: [...(projects.length ? [`Current workspace already has ${projects.length} project${projects.length === 1 ? "" : "s"}. Project restore should be reviewed before apply.`] : []), ...(users.length ? [`Current workspace already has ${users.length} user${users.length === 1 ? "" : "s"}. Username/email collisions need review.`] : [])],
      };
      setRestorePlan(plan);
      setStatus("Backup JSON staged for review. Nothing has been applied yet.");
    } catch (err) {
      setStatus(err instanceof Error ? err.message : "Restore JSON could not be parsed.");
    }
  }
  function approveRestorePlan() {
    if (!restorePlan) return;
    const approved = {
      ...restorePlan,
      approvedAt: new Date().toISOString(),
      restoreSections,
    };
    downloadJsonFile(`cluster-restore-plan-${new Date().toISOString().slice(0, 10)}.json`, approved);
    setStatus("Restore plan approved and downloaded. Apply still stays manual/staged until a real migration confirms it.");
  }
  return (
    <section className="import-tools-v127">
      <div className="management-header-row">
        <div>
          <p className="eyebrow">Imports</p>
          <h2>Import tools</h2>
          <p className="muted tight">Import users, task cards, project records, and Library documents in one controlled operation.</p>
        </div>
        <span className="soft-pill">CSV / JSON</span>
      </div>
      <div className="import-grid-v127">
        <article className="panel import-card-v127">
          <h3>Users CSV</h3>
          <p className="muted tight">Headers: username, employeeNumber, displayName, email, title, teamName, role, capacityHours.</p>
          <ClusterTextArea value={usersCsv} onChange={(event) => setUsersCsv(event.target.value)} />
          <ClusterButton type="button" className="" onClick={importUsers} variant="secondary">
            Import users
          </ClusterButton>
        </article>
        <article className="panel import-card-v127">
          <h3>Cards / tasks CSV</h3>
          <p className="muted tight">Headers: title, description, priority, labels.</p>
          <div className="field">
            <label>Target list</label>
            <ClusterNativeSelect value={targetListId} onChange={(event) => setTargetListId(event.target.value)}>
              {listOptions.map((option) => (
                <option key={option.list.id} value={option.list.id}>
                  {option.project.name} / {option.board.name} / {option.list.title}
                </option>
              ))}
            </ClusterNativeSelect>
          </div>
          <ClusterTextArea value={cardsCsv} onChange={(event) => setCardsCsv(event.target.value)} />
          <ClusterButton type="button" className="" onClick={importCards} variant="secondary">
            Import cards
          </ClusterButton>
        </article>
        <article className="panel import-card-v127">
          <h3>Projects JSON</h3>
          <p className="muted tight">Array or object with name, description, projectType, status, external, boardName.</p>
          <ClusterTextArea value={projectJson} onChange={(event) => setProjectJson(event.target.value)} />
          <ClusterButton type="button" className="" onClick={importProjectsJson} variant="secondary">
            Import projects
          </ClusterButton>
        </article>
        <article className="panel import-card-v127">
          <h3>Library bulk CSV</h3>
          <p className="muted tight">Headers: title, type, status, body, tags, versionLabel.</p>
          <div className="field">
            <label>Target project</label>
            <ClusterNativeSelect value={targetProjectId} onChange={(event) => setTargetProjectId(event.target.value)}>
              <option value="">No project</option>
              {projects.map((project) => (
                <option key={project.id} value={project.id}>
                  {project.name}
                </option>
              ))}
            </ClusterNativeSelect>
          </div>
          <ClusterTextArea value={libraryCsv} onChange={(event) => setLibraryCsv(event.target.value)} />
          <ClusterButton type="button" className="" onClick={importLibraryBulk} variant="secondary">
            Import library docs
          </ClusterButton>
        </article>
      </div>
      <section className="panel restore-review-v127">
        <div className="section-heading">
          <div>
            <p className="eyebrow">Restore review</p>
            <h3>Stage backup restore</h3>
            <p className="muted tight">Paste a backup/export JSON file, inspect the sections, choose what would be restored, then download a restore plan. Still staged. Still safer than YOLO restore.</p>
          </div>
        </div>
        <ClusterTextArea value={restoreText} onChange={(event) => setRestoreText(event.target.value)} placeholder="Paste Cluster backup/export JSON here..." />
        <div className="button-row">
          <ClusterButton type="button" className="" onClick={stageRestorePlan} variant="secondary">
            Stage restore review
          </ClusterButton>
          <ClusterButton type="button" className="" disabled={!restorePlan} onClick={approveRestorePlan} variant="primary">
            Approve restore plan
          </ClusterButton>
        </div>
        {restorePlan && (
          <div className="restore-plan-grid-v127">
            {Object.entries(restorePlan.sections).map(([key, count]) => (
              <label key={key} className="tool-check">
                <ClusterInput
                  type="checkbox"
                  checked={restoreSections[key] ?? false}
                  onChange={(event) =>
                    setRestoreSections((prev) => ({
                      ...prev,
                      [key]: event.target.checked,
                    }))
                  }
                />{" "}
                {levelLabel(key)} <span>{String(count)} records</span>
              </label>
            ))}
          </div>
        )}
        {restorePlan?.conflicts?.length ? (
          <div className="restore-conflicts-v127">
            {restorePlan.conflicts.map((item: string) => (
              <p key={item}>{item}</p>
            ))}
          </div>
        ) : null}
      </section>
      <section className="panel import-results-v127">
        <div className="section-heading compact">
          <div>
            <p className="eyebrow">Results</p>
            <h3>Latest import run</h3>
          </div>
          <span className="soft-pill">{preview.length}</span>
        </div>
        {preview.length ? (
          preview.map((item) => (
            <article key={item.id} className={item.status}>
              <strong>{item.title}</strong>
              <span>
                {levelLabel(item.type)} · {item.detail}
              </span>
              {item.error && <em>{item.error}</em>}
            </article>
          ))
        ) : (
          <div className="empty-state compact-empty">No imports run yet.</div>
        )}
      </section>
      {status && <div className="status-box system-status-box-v053">{status}</div>}
    </section>
  );
}

export const TOOL_INFRASTRUCTURE_CATALOG: Array<{
  key: ToolKey;
  label: string;
  group: "Planning" | "Workflow" | "Content";
  description: string;
}> = CLUSTER_ADMIN_CONFIGURABLE_TOOL_IDS.map((key) => {
  const definition = CLUSTER_TOOL_PERMISSION_MANIFEST[key];
  return {
    key,
    label: definition.label,
    group: definition.adminGroup || "Workflow",
    description: definition.description,
  };
});

export const TOOL_INFRASTRUCTURE_LABELS = Object.fromEntries(TOOL_INFRASTRUCTURE_CATALOG.map((tool) => [tool.key, tool.label])) as Record<ToolKey, string>;

export function ToolInfrastructurePage({ projects, settings, initialSection }: { projects: Project[]; settings?: Settings; initialSection?: string | null }) {
  const [activeTool, setActiveTool] = useState<ToolKey>("timeline");
  const [toolBrowseMode, setToolBrowseMode] = useState<"configure" | "directory">("directory");
  const [sourceControlOpen, setSourceControlOpen] = useState(initialSection === "source-control");
  const [toolSettingsOpen, setToolSettingsOpen] = useState(false);
  const [users, setUsers] = useState<UserActivitySummary[]>([]);
  const [snapshots, setSnapshots] = useState<ToolInfrastructureSnapshot[]>([]);
  const [status, setStatus] = useState("");
  const [loading, setLoading] = useState(true);
  const [hoursWeek, setHoursWeek] = useState(() => weekStart(new Date()));
  const [hoursUserId, setHoursUserId] = useState("");
  const [hoursProjectId, setHoursProjectId] = useState("");
  const [hoursEntries, setHoursEntries] = useState<TimeEntry[]>([]);
  const [hoursSummary, setHoursSummary] = useState<TimeSummary | null>(null);
  const [hoursEditorOpen, setHoursEditorOpen] = useState(false);
  const newHoursEntry = () => ({
    id: "",
    userId: "",
    title: "",
    description: "",
    projectId: "",
    boardId: "",
    cardId: "",
    startedAt: toDateTimeLocalInput(new Date().toISOString()),
    endedAt: toDateTimeLocalInput(new Date().toISOString()),
    durationMinutes: "",
    billable: false,
  });
  const [hoursEntry, setHoursEntry] = useState(newHoursEntry);
  const hoursBoards = useMemo(() => boardOptions(projects), [projects]);
  const hoursRangeStart = hoursWeek.toISOString();
  const hoursRangeEnd = addDays(hoursWeek, 7).toISOString();
  const hoursQuery = useMemo(() => {
    const params = new URLSearchParams({
      start: hoursRangeStart,
      end: hoursRangeEnd,
    });
    if (hoursUserId) params.set("userId", hoursUserId);
    if (hoursProjectId) params.set("projectId", hoursProjectId);
    return params.toString();
  }, [hoursRangeStart, hoursRangeEnd, hoursUserId, hoursProjectId]);
  const hoursWeekLabel = `${hoursWeek.toLocaleDateString([], { month: "short", day: "numeric" })} - ${addDays(hoursWeek, 6).toLocaleDateString([], { month: "short", day: "numeric" })}`;
  const hoursBillableMinutes = useMemo(() => hoursEntries.reduce((total, entry) => total + (entry.billable ? entry.computedDurationMinutes || 0 : 0), 0), [hoursEntries]);
  const hoursRunningCount = useMemo(() => hoursEntries.filter((entry) => entry.running).length, [hoursEntries]);
  const hoursUnlinkedCount = useMemo(() => hoursEntries.filter((entry) => !entry.projectId && !entry.cardId).length, [hoursEntries]);
  async function loadUsers() {
    const result = await api<UserActivitySummary[]>("/api/users");
    setUsers(result);
  }
  async function loadSnapshots() {
    const result = await api<{ tools: ToolInfrastructureSnapshot[] }>("/api/admin/tools");
    setSnapshots(result.tools || []);
  }
  async function refreshInfrastructure() {
    setLoading(true);
    setStatus("");
    try {
      await Promise.all([loadUsers(), loadSnapshots()]);
    } catch (error) {
      setStatus(error instanceof Error ? error.message : "Tool infrastructure could not be loaded.");
    } finally {
      setLoading(false);
    }
  }
  async function loadHours() {
    try {
      const [entries, summary] = await Promise.all([api<TimeEntry[]>(`/api/time/entries?${hoursQuery}`), api<TimeSummary>(`/api/time/summary?${hoursQuery}`)]);
      setHoursEntries(entries);
      setHoursSummary(summary);
    } catch (error) {
      setStatus(error instanceof Error ? error.message : "Scheduler records could not be loaded.");
    }
  }
  function exportHours() {
    const payload = {
      generatedAt: new Date().toISOString(),
      rangeStart: hoursRangeStart,
      rangeEnd: hoursRangeEnd,
      userId: hoursUserId || null,
      projectId: hoursProjectId || null,
      summary: hoursSummary,
      entries: hoursEntries.map((entry) => ({
        id: entry.id,
        userId: entry.userId,
        user: entry.user ? displayUserName(entry.user) : entry.userId,
        title: entry.title,
        project: entry.project?.name || null,
        card: entry.card?.title || null,
        startedAt: entry.startedAt,
        endedAt: entry.endedAt || null,
        minutes: entry.computedDurationMinutes,
        billable: entry.billable,
        source: entry.source,
      })),
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], {
      type: "application/json",
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `cluster-scheduler-hours-${hoursWeek.toISOString().slice(0, 10)}.json`;
    link.click();
    URL.revokeObjectURL(url);
    setStatus("Scheduler hours exported.");
  }
  useEffect(() => { void refreshInfrastructure(); }, []);
  useEffect(() => { if (initialSection === "source-control") { setSourceControlOpen(true); setToolSettingsOpen(true); } }, [initialSection]);
  useEffect(() => {
    if (activeTool === "scheduler") void loadHours();
  }, [activeTool, hoursQuery]);
  function resetHoursEditor() {
    setHoursEntry({
      ...newHoursEntry(),
      userId: hoursUserId || users[0]?.id || "",
      projectId: hoursProjectId || "",
    });
    setHoursEditorOpen(false);
  }
  function openHoursEditor() {
    setHoursEntry({
      ...newHoursEntry(),
      userId: hoursUserId || users[0]?.id || "",
      projectId: hoursProjectId || "",
    });
    setHoursEditorOpen(true);
  }
  function editHoursEntry(entry: TimeEntry) {
    setHoursEntry({
      id: entry.id,
      userId: entry.userId,
      title: entry.title,
      description: entry.description || "",
      projectId: entry.projectId || "",
      boardId: entry.boardId || "",
      cardId: entry.cardId || "",
      startedAt: toDateTimeLocalInput(entry.startedAt),
      endedAt: toDateTimeLocalInput(entry.endedAt || new Date().toISOString()),
      durationMinutes: String(entry.durationMinutes ?? entry.computedDurationMinutes ?? ""),
      billable: Boolean(entry.billable),
    });
    setHoursEditorOpen(true);
  }
  async function saveHoursEntry() {
    if (!hoursEntry.userId || !hoursEntry.title.trim()) {
      setStatus("User and title are required.");
      return;
    }
    const body = {
      userId: hoursEntry.userId,
      projectId: hoursEntry.projectId || null,
      boardId: hoursEntry.boardId || null,
      cardId: hoursEntry.cardId || null,
      title: hoursEntry.title.trim(),
      description: hoursEntry.description || null,
      startedAt: fromDateTimeLocalInput(hoursEntry.startedAt),
      endedAt: hoursEntry.endedAt ? fromDateTimeLocalInput(hoursEntry.endedAt) : null,
      durationMinutes: hoursEntry.durationMinutes ? Number(hoursEntry.durationMinutes) : null,
      billable: hoursEntry.billable,
    };
    try {
      if (hoursEntry.id)
        await api<TimeEntry>(`/api/time/entries/${hoursEntry.id}`, {
          method: "PUT",
          body: JSON.stringify(body),
        });
      else
        await api<TimeEntry>("/api/time/entries", {
          method: "POST",
          body: JSON.stringify(body),
        });
      setStatus(hoursEntry.id ? "Time entry corrected." : "Time entry created.");
      resetHoursEditor();
      await loadHours();
    } catch (error) {
      setStatus(error instanceof Error ? error.message : "Time entry could not be saved.");
    }
  }
  async function deleteHoursEntry(entry: TimeEntry) {
    if (!await confirmCluster({ title: "Delete time entry?", message: `Delete time entry "${entry.title}"?`, confirmLabel: "Delete entry", tone: "danger" })) return;
    try {
      await api(`/api/time/entries/${entry.id}`, { method: "DELETE" });
      setStatus("Time entry deleted.");
      await loadHours();
    } catch (error) {
      setStatus(error instanceof Error ? error.message : "Time entry could not be deleted.");
    }
  }
  const operationalCount = snapshots.filter((snapshot) => snapshot.status === "operational").length;
  const disabledCount = snapshots.filter((snapshot) => snapshot.status === "disabled").length;
  const activeSnapshot = snapshots.find((snapshot) => snapshot.key === activeTool);
  const activeToolMeta = TOOL_INFRASTRUCTURE_CATALOG.find((tool) => tool.key === activeTool) || TOOL_INFRASTRUCTURE_CATALOG[0];
  const visibleToolCatalog = TOOL_INFRASTRUCTURE_CATALOG;
  const toolGroups = Array.from(new Set(visibleToolCatalog.map((tool) => tool.group)));
  return (
    <WorkspacePageShell
      className="tool-infrastructure-page admin-workspace-v298"
      title="Tool Infrastructure"
      icon="tools"
      metrics={[
        { label: "Tools", value: snapshots.length || TOOL_INFRASTRUCTURE_CATALOG.length },
        { label: "Operational", value: operationalCount, tone: operationalCount === (snapshots.length || TOOL_INFRASTRUCTURE_CATALOG.length) ? "good" : "warning" },
        { label: "Disabled", value: disabledCount, tone: disabledCount ? "warning" : "neutral" },
      ]}
      actions={<ClusterButton variant="secondary" busy={loading} busyLabel="Refreshing…" onClick={() => void refreshInfrastructure()}><ClusterIcon name="refresh" />Refresh</ClusterButton>}
    >
      {status && (
        <div className="admin-workflow-status-v231 cluster-page-status" role="status">
          {status}
        </div>
      )}
      <div className="button-row" role="group" aria-label="Tool infrastructure views">
        <ClusterButton variant={toolBrowseMode === "directory" ? "primary" : "secondary"} onClick={() => setToolBrowseMode("directory")}>All tools</ClusterButton>
        <ClusterButton variant={toolBrowseMode === "configure" ? "primary" : "secondary"} onClick={() => setToolBrowseMode("configure")}>Tool configuration</ClusterButton>
      </div>
      {toolBrowseMode === "directory" ? <ToolDirectoryPanel onConfigure={(id: ClusterToolPermissionKey) => {
        if (!CLUSTER_ADMIN_CONFIGURABLE_TOOL_IDS.includes(id as ToolKey)) return;
        setSourceControlOpen(false);
        setActiveTool(id as ToolKey);
        setToolSettingsOpen(true);
        setToolBrowseMode("configure");
      }} /> : <div className={`tool-infrastructure-browser ${toolSettingsOpen ? "is-subpage" : "is-list"}`}>
        <aside className="panel tool-infrastructure-catalog">
          <header>
            <div>
              <strong>Tools</strong>
              <span>{TOOL_INFRASTRUCTURE_CATALOG.length} managed tools</span>
            </div>
          </header>
          <div className="tool-infrastructure-catalog-list">
            <section><h2>Development</h2><ClusterButton type="button" className={sourceControlOpen ? "active operational" : "operational"} onClick={() => { setSourceControlOpen(true); setToolSettingsOpen(true); }}><i /><span><strong>Source Control</strong><em>Git runtime, managed repositories, LFS, remotes, and repository defaults.</em></span><b>Native</b></ClusterButton></section>
            {toolGroups.map((group) => (
              <section key={group}>
                <h2>{group}</h2>
                {visibleToolCatalog
                  .filter((tool) => tool.group === group)
                  .map((tool) => {
                    const snapshot = snapshots.find((item) => item.key === tool.key);
                    return (
                      <ClusterButton type="button" key={tool.key} className={`${activeTool === tool.key ? "active" : ""} ${snapshot?.status || "degraded"}`} onClick={() => { setSourceControlOpen(false); setActiveTool(tool.key); setToolSettingsOpen(true); }}>
                        <i />
                        <span>
                          <strong>{tool.label}</strong>
                          <em>{tool.description}</em>
                        </span>
                        <b>{snapshot?.enabled === false ? "Off" : snapshot?.status === "operational" ? "On" : "Check"}</b>
                      </ClusterButton>
                    );
                  })}
              </section>
            ))}
          </div>
        </aside>
        <main className="tool-infrastructure-detail">
          {sourceControlOpen ? <><header className="panel tool-infrastructure-detail-header"><ClusterButton className="tool-infrastructure-back" type="button" onClick={() => { setSourceControlOpen(false); setToolSettingsOpen(false); }} variant="secondary">Back to tools</ClusterButton><div><span>Development · Cluster native</span><h2>Source Control</h2><p>Configure Git runtime, repository defaults, LFS, optional remotes, and repository infrastructure here.</p></div><dl><div><dt>Mode</dt><dd>Project native</dd></div><div><dt>Projects</dt><dd>{projects.length}</dd></div></dl></header><SourceControlAdminPage embedded /></> : <>
          <header className="panel tool-infrastructure-detail-header">
            <ClusterButton className="tool-infrastructure-back" type="button" onClick={() => setToolSettingsOpen(false)} variant="secondary">Back to tools</ClusterButton>
            <div>
              <span>
                {activeToolMeta.group} · {activeSnapshot?.status || "loading"}
              </span>
              <h2>{activeToolMeta.label}</h2>
              <p>{activeToolMeta.description}</p>
            </div>
            <dl>
              <div>
                <dt>Enabled</dt>
                <dd>{activeSnapshot?.enabled === false ? "No" : "Yes"}</dd>
              </div>
              <div>
                <dt>Records</dt>
                <dd>{activeSnapshot?.runtime?.records ?? 0}</dd>
              </div>
              <div>
                <dt>Active</dt>
                <dd>{activeSnapshot?.runtime?.active ?? 0}</dd>
              </div>
            </dl>
          </header>
          <AdminToolControls tool={activeTool} settings={settings as Record<string, any>} projects={projects} users={users} onUsersChanged={loadUsers} />

          {activeTool === "scheduler" && (
            <details className="panel admin-consolidated-details-v15 tool-infrastructure-time-admin-v15">
              <summary><span><strong>Advanced time administration</strong><small>Corrections, manual entries, export, and record-level cleanup. Routine scheduling stays in the Scheduler workspace.</small></span></summary>
              <section className="management-panel admin-hours-panel-v105 tool-infrastructure-hours">
              <div className="management-header-row">
                <div>
                  <h2>Recorded hours</h2>
                </div>
                <div className="button-row">
                  <ClusterButton type="button" className="" onClick={() => void loadHours()} variant="secondary">
                    Refresh
                  </ClusterButton>
                  <ClusterButton type="button" className="" onClick={exportHours} variant="secondary">
                    Export
                  </ClusterButton>
                  <ClusterButton type="button" className="" onClick={openHoursEditor} variant="primary">
                    Add entry
                  </ClusterButton>
                </div>
              </div>
              <div className="time-context-bar admin-hours-controls-v105 panel soft-panel-v071">
                <div className="week-switcher">
                  <ClusterButton type="button" className="" onClick={() => setHoursWeek(addDays(hoursWeek, -7))} variant="quiet" size="compact">
                    Previous
                  </ClusterButton>
                  <strong>{hoursWeekLabel}</strong>
                  <ClusterButton type="button" className="" onClick={() => setHoursWeek(weekStart(new Date()))} variant="quiet" size="compact">
                    This week
                  </ClusterButton>
                  <ClusterButton type="button" className="" onClick={() => setHoursWeek(addDays(hoursWeek, 7))} variant="quiet" size="compact">
                    Next
                  </ClusterButton>
                </div>
                <ClusterSelect
                  value={hoursUserId}
                  onChange={setHoursUserId}
                  ariaLabel="Hours user filter"
                  options={[
                    { value: "", label: "All users" },
                    ...users.map((member) => ({
                      value: member.id,
                      label: displayUserName(member),
                    })),
                  ]}
                />
                <ClusterSelect
                  value={hoursProjectId}
                  onChange={setHoursProjectId}
                  ariaLabel="Hours project filter"
                  options={[
                    { value: "", label: "All projects" },
                    ...projects.map((project) => ({
                      value: project.id,
                      label: project.name,
                    })),
                  ]}
                />
              </div>
              <TimeCorrectionRequestPanel projects={projects} users={users} adminView />
              <TimeRulesPanel projects={projects} currentUser={users.find((member) => member.id === hoursUserId) || null} entries={hoursEntries} blocks={[]} adminView />
              {hoursEditorOpen && (
                <section className="panel time-card composer-panel-v071 admin-hours-manual-v114">
                  <div className="section-heading">
                    <div>
                      <h3>{hoursEntry.id ? "Correct time entry" : "Manual time entry"}</h3>
                    </div>
                    <ClusterButton type="button" className="" onClick={resetHoursEditor} variant="quiet" size="compact">
                      Close
                    </ClusterButton>
                  </div>
                  <div className="time-form-grid clean-form-grid">
                    <div className="field">
                      <label>User</label>
                      <ClusterSelect
                        value={hoursEntry.userId}
                        onChange={(userId) => setHoursEntry((current) => ({ ...current, userId }))}
                        ariaLabel="Time entry user"
                        options={[
                          { value: "", label: "Select user" },
                          ...users.map((member) => ({
                            value: member.id,
                            label: displayUserName(member),
                          })),
                        ]}
                      />
                    </div>
                    <div className="field">
                      <label>Title</label>
                      <ClusterTextInput
                        value={hoursEntry.title}
                        onChange={(event) =>
                          setHoursEntry((current) => ({
                            ...current,
                            title: event.target.value,
                          }))
                        }
                      />
                    </div>
                    <div className="field">
                      <label>Started</label>
                      <ClusterTextInput
                        type="datetime-local"
                        value={hoursEntry.startedAt}
                        onChange={(event) =>
                          setHoursEntry((current) => ({
                            ...current,
                            startedAt: event.target.value,
                          }))
                        }
                      />
                    </div>
                    <div className="field">
                      <label>Ended</label>
                      <ClusterTextInput
                        type="datetime-local"
                        value={hoursEntry.endedAt}
                        onChange={(event) =>
                          setHoursEntry((current) => ({
                            ...current,
                            endedAt: event.target.value,
                          }))
                        }
                      />
                    </div>
                    <div className="field">
                      <label>Minutes override</label>
                      <NumberStepper
                        min={0}
                        value={hoursEntry.durationMinutes}
                        onValueChange={(value) =>
                          setHoursEntry((current) => ({
                            ...current,
                            durationMinutes: value,
                          }))
                        }
                        placeholder="Auto"
                        ariaLabel="Minutes override"
                      />
                    </div>
                    <div className="field">
                      <label>Project</label>
                      <ClusterSelect
                        value={hoursEntry.projectId}
                        onChange={(projectId) =>
                          setHoursEntry((current) => ({
                            ...current,
                            projectId,
                            boardId: "",
                            cardId: "",
                          }))
                        }
                        ariaLabel="Time entry project"
                        options={[
                          { value: "", label: "No project" },
                          ...projects.map((project) => ({
                            value: project.id,
                            label: project.name,
                          })),
                        ]}
                      />
                    </div>
                    <div className="field">
                      <label>Board</label>
                      <ClusterSelect
                        value={hoursEntry.boardId}
                        onChange={(boardId) =>
                          setHoursEntry((current) => ({
                            ...current,
                            boardId,
                            cardId: "",
                          }))
                        }
                        ariaLabel="Time entry board"
                        options={[
                          { value: "", label: "No board" },
                          ...hoursBoards
                            .filter((board) => !hoursEntry.projectId || board.projectId === hoursEntry.projectId)
                            .map((board) => ({
                              value: board.id,
                              label: `${board.projectName} / ${board.name}`,
                            })),
                        ]}
                      />
                    </div>
                    <div className="field">
                      <label>Card</label>
                      <CardSelect
                        boardId={hoursEntry.boardId}
                        value={hoursEntry.cardId}
                        onChange={(value) =>
                          setHoursEntry((current) => ({
                            ...current,
                            cardId: value,
                          }))
                        }
                      />
                    </div>
                    <div className="field full">
                      <label>Description</label>
                      <ClusterTextArea
                        value={hoursEntry.description}
                        onChange={(event) =>
                          setHoursEntry((current) => ({
                            ...current,
                            description: event.target.value,
                          }))
                        }
                      />
                    </div>
                    <label className="toggle-line">
                      <ClusterInput
                        type="checkbox"
                        checked={hoursEntry.billable}
                        onChange={(event) =>
                          setHoursEntry((current) => ({
                            ...current,
                            billable: event.target.checked,
                          }))
                        }
                      />{" "}
                      Billable
                    </label>
                    <ClusterButton type="button" className="" onClick={() => void saveHoursEntry()} variant="primary">
                      {hoursEntry.id ? "Save correction" : "Create entry"}
                    </ClusterButton>
                  </div>
                </section>
              )}
              <div className="admin-hours-summary-v105">
                <div className="mini-metric">
                  <span>Total</span>
                  <strong>{minutesToHuman(hoursSummary?.totalMinutes || 0)}</strong>
                </div>
                <div className="mini-metric">
                  <span>Entries</span>
                  <strong>{hoursSummary?.entryCount || 0}</strong>
                </div>
                <div className="mini-metric">
                  <span>Billable</span>
                  <strong>{minutesToHuman(hoursBillableMinutes)}</strong>
                </div>
                <div className="mini-metric">
                  <span>Unlinked</span>
                  <strong>{hoursUnlinkedCount}</strong>
                </div>
                <div className="mini-metric">
                  <span>Running</span>
                  <strong>{hoursRunningCount}</strong>
                </div>
              </div>
              <div className="admin-hours-list-v105">
                {hoursEntries.length ? (
                  hoursEntries.map((entry) => (
                    <div className={`time-entry-row admin-time-entry-row-v105 ${entry.running ? "running" : ""}`} key={entry.id}>
                      <div>
                        <strong>{entry.title}</strong>
                        <span>
                          {displayUserName(entry.user)} · {entry.project?.name || "No project"}
                          {entry.card ? ` · ${entry.card.title}` : ""}
                        </span>
                      </div>
                      <div>
                        <b>{minutesToHuman(entry.computedDurationMinutes)}</b>
                        <span>
                          {compactDateTime(entry.startedAt)}
                          {entry.endedAt ? ` - ${compactDateTime(entry.endedAt)}` : " · running"}
                        </span>
                      </div>
                      <div>
                        <b>{entry.billable ? "Billable" : "Internal"}</b>
                        <span>{entry.source || "manual"}</span>
                      </div>
                      <div className="row-actions">
                        <ClusterButton type="button" className="" onClick={() => editHoursEntry(entry)} variant="quiet" size="compact">
                          Edit
                        </ClusterButton>
                        <ClusterButton type="button" className="danger-micro" onClick={() => void deleteHoursEntry(entry)} variant="quiet" size="compact">
                          Delete
                        </ClusterButton>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="empty-state compact-empty">No entries.</div>
                )}
              </div>
              </section>
            </details>
          )}
            </>}
        </main>
      </div>}
    </WorkspacePageShell>
  );
}

export function AdminReportsPanel({ projects, users, onOpenProject }: { projects: Project[]; users: UserActivitySummary[]; onOpenProject?: (projectId: string) => void }) {
  const [period, setPeriod] = useState<"day" | "7d" | "30d" | "custom">("7d");
  const [projectId, setProjectId] = useState("all");
  const [startDate, setStartDate] = useState(() => new Date(Date.now() - 6 * 86400000).toISOString().slice(0, 10));
  const [endDate, setEndDate] = useState(() => new Date().toISOString().slice(0, 10));
  const [events, setEvents] = useState<ActivityEvent[]>([]);
  const [timeEntries, setTimeEntries] = useState<TimeEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState("");
  const [requestProjectId, setRequestProjectId] = useState("");
  const [requestDueDate, setRequestDueDate] = useState(() => new Date(Date.now() + 3 * 86400000).toISOString().slice(0, 10));
  const [requestPriority, setRequestPriority] = useState<Priority>("medium");
  const [requestNote, setRequestNote] = useState("");
  const [requests, setRequests] = useServerState<OperationsReportRequest[]>("studio", "operations.report-requests", []);
  const range = useMemo(() => {
    const end = new Date(`${endDate}T23:59:59.999`);
    const today = new Date();
    const derivedEnd = period === "custom" || period === "day" ? end : new Date(today.getFullYear(), today.getMonth(), today.getDate(), 23, 59, 59, 999);
    const derivedStart = period === "day" ? new Date(derivedEnd.getFullYear(), derivedEnd.getMonth(), derivedEnd.getDate()) : period === "30d" ? new Date(derivedEnd.getTime() - 29 * 86400000) : period === "7d" ? new Date(derivedEnd.getTime() - 6 * 86400000) : new Date(`${startDate}T00:00:00`);
    return { start: derivedStart, end: derivedEnd };
  }, [period, startDate, endDate]);
  async function loadReport() {
    setLoading(true);
    setStatus("");
    try {
      const timeParams = new URLSearchParams({
        start: range.start.toISOString(),
        end: range.end.toISOString(),
      });
      if (projectId !== "all") timeParams.set("projectId", projectId);
      const [activityRows, hoursRows] = await Promise.all([api<ActivityEvent[]>("/api/activity?limit=500"), api<TimeEntry[]>(`/api/time/entries?${timeParams}`).catch(() => [])]);
      setEvents(
        activityRows.filter((event) => {
          const time = new Date(event.createdAt).getTime();
          return time >= range.start.getTime() && time <= range.end.getTime() && (projectId === "all" || event.project?.id === projectId);
        }),
      );
      setTimeEntries(hoursRows);
    } catch (error) {
      setStatus(error instanceof Error ? error.message : "Report data could not load.");
    } finally {
      setLoading(false);
    }
  }
  useEffect(() => {
    void loadReport();
  }, [period, projectId, startDate, endDate]);
  const projectRows = useMemo(() => {
    const scoped = projectId === "all" ? projects.filter((project) => !project.archived) : projects.filter((project) => project.id === projectId);
    return scoped
      .map((project) => {
        const projectEvents = events.filter((event) => event.project?.id === project.id);
        const projectHours = timeEntries.filter((entry) => entry.projectId === project.id).reduce((sum, entry) => sum + (entry.computedDurationMinutes || 0), 0);
        const risk = projectEvents.filter((event) => /blocked|failed|error|deleted|archived/i.test(`${event.type} ${event.title} ${event.message || ""}`)).length;
        return {
          project,
          events: projectEvents.length,
          hours: projectHours,
          risk,
          gaps: projectSetupGaps(project),
        };
      })
      .sort((a, b) => b.risk - a.risk || b.events - a.events);
  }, [projects, projectId, events, timeEntries]);
  const uniqueActors = new Set(events.map((event) => event.user?.id).filter(Boolean)).size;
  const totalMinutes = timeEntries.reduce((sum, entry) => sum + (entry.computedDurationMinutes || 0), 0);
  const riskEvents = events.filter((event) => /blocked|failed|error|deleted|archived/i.test(`${event.type} ${event.title} ${event.message || ""}`));
  async function requestProjectReport() {
    const project = projects.find((item) => item.id === requestProjectId);
    if (!project) {
      setStatus("Select a project.");
      return;
    }
    const leadId = projectAssignedIds(project)[0] || null;
    const targetList = project.boards.flatMap((board) => board.lists || []).find((list) => !list.isDone) || project.boards.flatMap((board) => board.lists || [])[0];
    const requestedAt = new Date().toISOString();
    if (!targetList) {
      setRequests(
        [
          {
            id: localId("report-request"),
            projectId: project.id,
            projectName: project.name,
            requestedAt,
            dueDate: requestDueDate,
            priority: requestPriority,
            assigneeId: leadId,
            status: "unavailable" as const,
            note: requestNote.trim(),
          },
          ...requests,
        ].slice(0, 100),
      );
      setStatus("The project has no board list. Create a board before requesting a lead report.");
      return;
    }
    try {
      const card = await api<any>("/api/cards", {
        method: "POST",
        body: JSON.stringify({
          listId: targetList.id,
          title: `Project report: ${project.name}`,
          description: [`Operations requested a project report for ${range.start.toLocaleDateString()} through ${range.end.toLocaleDateString()}.`, requestNote.trim()].filter(Boolean).join("\n\n"),
          priority: requestPriority,
          dueDate: requestDueDate ? new Date(`${requestDueDate}T17:00:00`).toISOString() : null,
          labels: ["report-request", "operations"],
          assigneeId: leadId,
        }),
      });
      setRequests(
        [
          {
            id: localId("report-request"),
            projectId: project.id,
            projectName: project.name,
            requestedAt,
            dueDate: requestDueDate,
            priority: requestPriority,
            assigneeId: leadId,
            cardId: card.id,
            status: "requested" as const,
            note: requestNote.trim(),
          },
          ...requests,
        ].slice(0, 100),
      );
      setRequestNote("");
      setStatus(`Report requested from ${leadId ? displayUserName(users.find((user) => user.id === leadId) || ({ username: "project lead" } as any)) : "the project team"}.`);
    } catch (error) {
      setStatus(error instanceof Error ? error.message : "Report request could not be created.");
    }
  }
  function exportReport() {
    downloadJsonFile(`cluster-operations-report-${range.start.toISOString().slice(0, 10)}-${range.end.toISOString().slice(0, 10)}.json`, {
      generatedAt: new Date().toISOString(),
      range: { start: range.start, end: range.end },
      projectId: projectId === "all" ? null : projectId,
      summary: {
        events: events.length,
        people: uniqueActors,
        minutes: totalMinutes,
        risks: riskEvents.length,
      },
      projects: projectRows.map((row) => ({
        id: row.project.id,
        name: row.project.name,
        status: row.project.status,
        events: row.events,
        minutes: row.hours,
        risks: row.risk,
        setupGaps: row.gaps,
      })),
      activity: events,
    });
  }
  return (
    <section className="operations-reports">
      <header className="operations-reports-head">
        <div>
          <h2>Reports</h2>
          <span>Generate an operational snapshot or assign a report task to a project lead.</span>
        </div>
        <div className="button-row">
          <ClusterButton type="button" className="" onClick={() => void loadReport()} disabled={loading} variant="secondary">
            {loading ? "Loading" : "Refresh"}
          </ClusterButton>
          <ClusterButton type="button" className="" onClick={exportReport} variant="primary">
            Export
          </ClusterButton>
        </div>
      </header>
      <section className="panel operations-report-filters">
        <label>
          <span>Period</span>
          <ClusterNativeSelect value={period} onChange={(event) => setPeriod(event.target.value as typeof period)}>
            <option value="day">Specific day</option>
            <option value="7d">Last 7 days</option>
            <option value="30d">Last 30 days</option>
            <option value="custom">Custom range</option>
          </ClusterNativeSelect>
        </label>
        {period === "day" && (
          <label>
            <span>Day</span>
            <ClusterTextInput type="date" value={endDate} onChange={(event) => setEndDate(event.target.value)} />
          </label>
        )}
        {period === "custom" && (
          <>
            <label>
              <span>Start</span>
              <ClusterTextInput type="date" value={startDate} onChange={(event) => setStartDate(event.target.value)} />
            </label>
            <label>
              <span>End</span>
              <ClusterTextInput type="date" value={endDate} onChange={(event) => setEndDate(event.target.value)} />
            </label>
          </>
        )}
        <label>
          <span>Project</span>
          <ClusterNativeSelect value={projectId} onChange={(event) => setProjectId(event.target.value)}>
            <option value="all">All projects</option>
            {projects
              .filter((project) => !project.archived)
              .map((project) => (
                <option key={project.id} value={project.id}>
                  {project.name}
                </option>
              ))}
          </ClusterNativeSelect>
        </label>
      </section>
      <div className="operations-report-metrics">
        <span>
          <b>{events.length}</b>
          <em>events</em>
        </span>
        <span>
          <b>{uniqueActors}</b>
          <em>contributors</em>
        </span>
        <span>
          <b>{minutesToHuman(totalMinutes)}</b>
          <em>tracked</em>
        </span>
        <span className={riskEvents.length ? "attention" : "good"}>
          <b>{riskEvents.length}</b>
          <em>risk signals</em>
        </span>
      </div>
      <div className="operations-report-layout">
        <section className="panel operations-report-projects">
          <header>
            <strong>Project summary</strong>
            <span>
              {range.start.toLocaleDateString()} – {range.end.toLocaleDateString()}
            </span>
          </header>
          <div>
            {projectRows.length ? (
              projectRows.map((row) => (
                <ClusterButton type="button" key={row.project.id} onClick={() => onOpenProject?.(row.project.id)}>
                  <span>
                    <strong>{row.project.name}</strong>
                    <em>
                      {projectStatusLabel(row.project)} · {row.gaps.length ? `${row.gaps.length} setup gap${row.gaps.length === 1 ? "" : "s"}` : "ready"}
                    </em>
                  </span>
                  <b>{row.events} events</b>
                  <b>{minutesToHuman(row.hours)}</b>
                  <b className={row.risk ? "attention" : "good"}>{row.risk} risk</b>
                </ClusterButton>
              ))
            ) : (
              <div className="empty-state compact-empty">No projects in this report.</div>
            )}
          </div>
        </section>
        <aside className="panel operations-report-request">
          <header>
            <strong>Request project report</strong>
            <span>Creates an assigned board card for the project lead.</span>
          </header>
          <label>
            <span>Project</span>
            <ClusterNativeSelect value={requestProjectId} onChange={(event) => setRequestProjectId(event.target.value)}>
              <option value="">Select project</option>
              {projects
                .filter((project) => !project.archived)
                .map((project) => (
                  <option key={project.id} value={project.id}>
                    {project.name}
                  </option>
                ))}
            </ClusterNativeSelect>
          </label>
          <div className="two-col">
            <label>
              <span>Due</span>
              <ClusterTextInput type="date" value={requestDueDate} onChange={(event) => setRequestDueDate(event.target.value)} />
            </label>
            <label>
              <span>Priority</span>
              <ClusterNativeSelect value={requestPriority} onChange={(event) => setRequestPriority(event.target.value as Priority)}>
                <option value="low">Low</option>
                <option value="medium">Medium</option>
                <option value="high">High</option>
                <option value="urgent">Urgent</option>
              </ClusterNativeSelect>
            </label>
          </div>
          <label>
            <span>Focus</span>
            <ClusterTextArea value={requestNote} onChange={(event) => setRequestNote(event.target.value)} placeholder="Milestones, blockers, budget, delivery risk, or decisions needed." />
          </label>
          <ClusterButton type="button" className="" onClick={() => void requestProjectReport()} disabled={!requestProjectId} variant="primary">
            Request report
          </ClusterButton>
          <div className="operations-report-request-history">
            {requests.slice(0, 5).map((request) => (
              <ClusterButton type="button" key={request.id} onClick={() => onOpenProject?.(request.projectId)}>
                <span>
                  <strong>{request.projectName}</strong>
                  <em>{request.status === "requested" ? `Due ${new Date(request.dueDate).toLocaleDateString()}` : "Board required"}</em>
                </span>
                <b>{levelLabel(request.priority)}</b>
              </ClusterButton>
            ))}
          </div>
        </aside>
      </div>
      {status && <div className="status-box slim">{status}</div>}
    </section>
  );
}

export const ADMIN_PAGE_DEPENDENCIES: AdminPageDependencies = { PersistenceBridgePanel, WorkLinkManager, DataModelStandardsPanel, AdminMaintenanceToolsPanel, PermissionMatrixControls, TemplateStudioPanel, toDateInputValue, USER_DEPARTMENT_PRESETS, USER_TEAM_PRESETS, enabledStudioDepartmentsFromSettings, enabledStudioRolesFromSettings, rolePermissionsFromSettings, projectTypePresetsFromSettings, PROJECT_INTAKE_TEMPLATES, projectTypeBadge, readFileAsDataUrl, UserEditorForm, StabilizationCenterPanel, ImportToolsPanel, TOOL_INFRASTRUCTURE_CATALOG, AdminReportsPanel, getProjectPermission, projectPermissionReason };
